import fs from 'node:fs'
import path from 'node:path'
import assert from 'node:assert/strict'
import { chromium } from '../tests/browser/node_modules/playwright/index.mjs'
import { browserOptions } from '../tests/browser/environment.mjs'

const report = 'docs/refinement/PHASE_3_1_REPORT.md'
let links = 0
for (const match of fs.readFileSync(report, 'utf8').matchAll(/\]\(([^)]+)\)/g)) {
  assert.ok(fs.existsSync(path.resolve(path.dirname(report), match[1])), match[1])
  links++
}
const browser = await chromium.launch(browserOptions)
try {
  const page = await browser.newPage()
  const errors = []
  page.on('pageerror', error => errors.push(error.message))
  await page.goto('http://localhost:5173/cent-s/docs/refinement/evidence/phase-3-1/index.html')
  assert.equal(await page.locator('article').count(), 8)
  for (const width of [1440, 390]) {
    await page.setViewportSize({ width, height: 900 })
    assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1))
    await page.screenshot({ path: `docs/refinement/evidence/phase-3-1/review-index-${width}.png` })
  }
  assert.deepEqual(errors, [])
  fs.writeFileSync('docs/refinement/evidence/phase-3-1/documentation-validation.json', JSON.stringify({ success: true, reportLinks: links, matchedPairs: 8, indexWidths: [1440, 390], noOverflow: true, errors }, null, 2))
  console.log('Report links and comparison index passed at desktop and mobile widths')
} finally { await browser.close() }

