mpt.questions.map((q, i) => <button className={i === index ? 'active' : answers[q.id] != null ? 'answered' : ''} key={q.id} onClick={() => setIndex(i)}>{i + 1}</button>)}</div><section className="card sim-question"><span className="eyebrow">{question.topic}</span><span className="cent-tag">{({ easy: 'آسان', medium: 'متوسط', hard: 'سخت' })[question.difficulty]}</span><h2 dir="auto">{question.text}</h2>{question.figureSvg && <img className="cent-question-figure" alt="شکل سؤال" src={`data:image/svg+xml;charset=utf-8,${encodeURIComponent(question.figureSvg)}`}/>}<div className="options-list">{question.options.map((option, i) => <button key={i} disabled={busy || remaining <= 0} className={answers[question.id] === i ? 'selected' : ''} onClick={() => setAnswers(a => ({ ...a, [question.id]: i }))}><span>{['الف', 'ب', 'ج', 'د', 'هـ', 'و'][i]}</span><b dir="auto">{option}</b></button>)}</div><div className="question-actions"><button className="button button-ghost" disabled={index <= 0} onClick={() => setIndex(i => i - 1)}><ArrowRight size={16}/> قبلی</button><button className="button button-ghost" onClick={() => setAnswers(a => ({ ...a, [question.id]: null }))}>پاک‌کردن پاسخ</button>{index < attempt.questions.length - 1 ? <button className="button button-secondary" onClick={() => setIndex(i => i + 1)}>بعدی <ArrowLeft size={16}/></button> : <button className="button button-primary" disabled={busy || remaining <= 0} onClick={submit}>{busy ? 'در حال ثبت…' : 'ثبت و دیدن نتیجه'}</button>}</div>{remaining <= 0 && <p className="notice">زمان آزمون پایان یافته است. <button className="button button-ghost" onClick={() => { sessionStorage.removeItem(storageKey); requestId.current = crypto.randomUUID(); setAttempt(null) }}>آزمون تازه</button></p>}</section></>}</div>
