import assert from 'node:assert/strict'
import {existsSync,readFileSync,writeFileSync} from 'node:fs'
import {resolve,dirname} from 'node:path'
import {chromium} from '../tests/browser/node_modules/playwright/index.mjs'

const files=['docs/refinement/PHASE_4_REPORT.md','docs/refinement/evidence/phase-4/index.html','docs/refinement/evidence/phase-4/README.md']
let links=0
for(const file of files){
 const text=readFileSync(file,'utf8')
 const references=file.endsWith('.html')?[...text.matchAll(/(?:src|href)="([^"]+)"/g)].map(match=>match[1]):[...text.matchAll(/\]\(([^)]+)\)/g)].map(match=>match[1])
 for(const reference of references){if(reference.startsWith('#')||reference.includes('://'))continue;const path=resolve(dirname(file),reference.split('#')[0]);assert.ok(existsSync(path),`${file}: ${reference}`);links++}
}
const browser=await chromium.launch({channel:'chrome',headless:true})
const observations=[],errors=[]
try{
 const page=await browser.newPage()
 page.on('pageerror',error=>errors.push(error.message))
 for(const width of [1440,390]){
  await page.setViewportSize({width,height:1000})
  await page.goto('http://127.0.0.1:5174/cent-s/docs/refinement/evidence/phase-4/index.html')
  assert.equal(await page.locator('article').count(),13)
  await page.evaluate(async()=>{const imgs=[...document.images];for(const img of imgs)img.loading='eager';await Promise.all(imgs.map(img=>img.decode()))})
  const dimensions=await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth}))
  assert.ok(dimensions.scroll<=dimensions.width+1)
  observations.push({width,...dimensions,articles:13})
 }
 assert.deepEqual(errors,[])
 writeFileSync('docs/refinement/evidence/phase-4/documentation-validation.json',JSON.stringify({success:true,links,observations,errors,noAdditionalScreenshots:true},null,2))
 console.log(`Review links/gallery passed (${links} links, 13 decoded AFTER images, desktop/mobile without overflow).`)
}finally{await browser.close()}

